import json

# Load the test input grid
with open('/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen-3/play/users/u066/system/state/workspace/programs/task-f1003437.json', 'r') as f:
    test_input = json.load(f)

print(f"Test input shape: {len(test_input)}x{len(test_input[0])}")
print(f"First few rows:")
for i in range(min(8, len(test_input))):
    print(f"  Row {i}: {test_input[i][:15]}...")

# Find all unique marker row patterns
def get_marker_pattern(row):
    """Get (c0, c4, c8) pattern for a row."""
    try:
        c0 = row[0] if len(row) > 0 else 0
        c4 = row[4] if len(row) > 4 else 0
        c8 = row[8] if len(row) > 8 else 0
        return (c0, c4, c8)
    except:
        return (0, 0, 0)

def is_marker_row(pattern):
    """Check if pattern contains any marker value."""
    markers = [3, 4, 7]
    return any(p in markers for p in pattern)

def map_val(v):
    """Map marker value: 1→9, 3→3, 4→4, 7→7, 9→9, others→9"""
    if v == 1:
        return 9
    elif v == 9:
        return 9
    else:
        return v

def transform_row(row):
    """Transform a single row to output row."""
    pattern = get_marker_pattern(row)
    c0, c4, c8 = pattern

    # pos0 = c0 (mapped)
    pos0 = map_val(c0)

    # pos1 = c4 (mapped) if c4 != c0, else 9
    if c4 in [3, 4, 7]:
        if c4 != c0:
            pos1 = map_val(c4)
        else:
            pos1 = 9
    else:
        pos1 = 9

    # pos2 = c8 (mapped) if c8 (mapped) != c4 (mapped), else 9
    c8_mapped = map_val(c8)
    c4_mapped = map_val(c4)
    if c8 in [3, 4, 7]:
        if c8_mapped != c4_mapped:
            pos2 = c8_mapped
        else:
            pos2 = 9
    else:
        pos2 = 9

    return [pos0, pos1, pos2]

# Process all rows
output_rows = []
seen_patterns = set()
first_occurrence_map = {}

for i, row in enumerate(test_input):
    pattern = get_marker_pattern(row)
    if is_marker_row(pattern):
        if pattern not in seen_patterns:
            seen_patterns.add(pattern)
            first_occurrence_map[pattern] = i
            output_rows.append(transform_row(row))
        else:
            # Pattern seen before, check if it's a spacer or copy
            output_rows.append([9, 9, 9])

print(f"\nUnique marker patterns: {len(seen_patterns)}")
print(f"First occurrences: {first_occurrence_map}")
print(f"\nOutput rows:")
for i, r in enumerate(output_rows):
    print(f"  {i}: {r}")

# Save output
output_grid = output_rows
output_grid.append([9,9,9])
output_grid.append([9,9,9])
output_grid.append([9,9,9])
output_grid.append([9,9,9])
output_grid.append([9,9,9])
